function testOnERC721ReceivedCycles() public {
        unchecked {
            uint256 n = 8;
            _TestTemps[] memory t = new _TestTemps[](n);
            for (uint256 i; i != n; ++i) {
                t[i] = _testTemps();
                if (i != 0) {
                    vm.prank(t[i].owner);
                    MockERC721(_erc721)
                        .safeTransferFrom(t[i].owner, address(t[i - 1].account), t[i].tokenId);
                    t[i].owner = address(t[i - 1].account);
                }
            }
            for (uint256 i; i != n; ++i) {
                for (uint256 j = i; j != n; ++j) {
                    vm.prank(t[i].owner);
                    vm.expectRevert(ERC6551.SelfOwnDetected.selector);
                    MockERC721(_erc721)
                        .safeTransferFrom(t[i].owner, address(t[j].account), t[i].tokenId);
                }
                for (uint256 j; j != i; ++j) {
                    vm.prank(t[i].owner);
                    MockERC721(_erc721)
                        .safeTransferFrom(t[i].owner, address(t[j].account), t[i].tokenId);
                    vm.prank(address(t[j].account));
                    MockERC721(_erc721)
                        .safeTransferFrom(address(t[j].account), t[i].owner, t[i].tokenId);
                }
            }

            _TestTemps memory u = _testTemps();
            vm.prank(u.owner);
            MockERC721(_erc721).safeTransferFrom(u.owner, address(t[n - 1].account), u.tokenId);
        }
    }

