function testInitializeReinititalize(uint256) public {
        MockInitializable.Args memory a = _args();

        if (a.recurse) {
            vm.expectRevert(Initializable.InvalidInitialization.selector);
            if (_random() & 1 == 0) {
                m.initialize(a);
            } else {
                m.reinitialize(a);
            }
            return;
        }

        if (_random() & 1 == 0) {
            _expectEmitInitialized(1);
            m.initialize(a);
            a.version = 1;
        } else {
            _expectEmitInitialized(a.version);
            m.reinitialize(a);
        }
        assertEq(m.x(), a.x);
        _checkVersion(a.version);

        if (_random() & 1 == 0) {
            vm.expectRevert(Initializable.InvalidInitialization.selector);
            m.initialize(a);
        }
        if (_random() & 1 == 0) {
            vm.expectRevert(Initializable.InvalidInitialization.selector);
            m.reinitialize(a);
        }
        if (_random() & 1 == 0) {
            a.version = m.version();
            uint64 newVersion = uint64(_random());
            if (newVersion > a.version) {
                a.version = newVersion;
                m.reinitialize(a);
                _checkVersion(a.version);
            }
        }
    }

