            for (uint256 k; k != 2; ++k) {
                for (uint256 i; i != n; ++i) {
                    uint256 j = o + i * 2;
                    generalMaps[k].set(j, _hash(j), bitWidth);
                }
            }
            for (uint256 k; k != 2; ++k) {
                for (uint256 i; i != n; ++i) {
                    uint256 j = o + i * 2 + 1;
                    generalMaps[k].set(j, _hash(j), bitWidth);
                }
            }
            for (uint256 k; k != 2; ++k) {
                for (uint256 i; i != n; ++i) {
                    uint256 j = o + i * 2;
                    assertEq(generalMaps[k].get(j, bitWidth), _hash(j) & valueMask);
                    j = j + 1;
