function testRLPMemory(bytes32) public returns (LibRLP.List memory l) {
        while (true) {
            uint256 r = _random();
            if (r & 0x0003 == 0) {
                _maybeBzztMemory();
                l.p(_randomBytes());
                _checkMemory(l);
            }
            if (r & 0x0030 == 0) {
                if (_random() & 1 == 0) {
                    l.p(_randomNonZeroAddress());
                } else {
                    l.p(_random());
                }
                _checkMemory(l);
                _maybeBzztMemory();
            }
            if (r & 0x0100 == 0) {
                l.p(_testRLPP(0));
                _checkMemory(l);
            }
            if (r & 0x1000 == 0) break;
        }
        _checkMemory(l.encode());
    }

