function testHasDuplicateHashmapCapacityTrick(uint256 n) public pure {
        n = n & 0x7fffffff;
        uint256 c;
        /// @solidity memory-safe-assembly
        assembly {
            let w := not(0x1f) // `-0x20`.
            let t := mul(0x30, n)
            c := or(shr(1, t), t)
            c := or(shr(2, c), c)
            c := or(shr(4, c), c)
            c := or(shr(8, c), c)
            c := and(w, or(shr(16, c), c))
            c := add(0x20, c)
        }
        uint256 t = n + (n >> 1);
        t |= t >> 1;
        t |= t >> 2;
        t |= t >> 4;
        t |= t >> 8;
        t |= t >> 16;
        t |= t >> 32;
        t |= t >> 64;
        t |= t >> 128;
        t += 1;
        t = t << 5;
        assert(c == t && n >> 31 == 0);
    }

function testBumpSlot(bytes32 s, uint256 c) public {
        c = c & 0xffffffffffffffffff;
        LibStorage.Bump storage bump = LibStorage.bump(s);
        bump._current = c;
        assertEq(
            bump.slot(),
            keccak256(abi.encodePacked(s, uint32(_BUMPED_STORAGE_REF_SLOT_SEED), uint216(c)))
        );
        bump.invalidate();
        assertEq(
            bump.slot(),
            keccak256(abi.encodePacked(s, uint32(_BUMPED_STORAGE_REF_SLOT_SEED), uint216(c + 1)))
        );
    }

