function testCountLeadingNonZeroBytes(bytes32 s) public {
        uint256 expected;
        uint256 computed;
        /// @solidity memory-safe-assembly
        assembly {
            let n := 0
            for {} // Scan for '\0'.
             byte(n, s) { n := add(n, 1) } {}
            expected := n
            let m := 0x7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F7F
            let x := not(or(or(add(and(s, m), m), s), m))
            computed := 0x20
            if x {
                let r := shl(7, lt(0xffffffffffffffffffffffffffffffff, x))
                r := or(r, shl(6, lt(0xffffffffffffffff, shr(r, x))))
                r := or(r, shl(5, lt(0xffffffff, shr(r, x))))
                r := or(r, shl(4, lt(0xffff, shr(r, x))))
                r := xor(31, or(shr(3, r), lt(0xff, shr(r, x))))
                computed := r
            }
        }
        assertEq(computed, expected);
    }

function testLifebuoyCreateDeployment(address owner, uint256 r) public {
        // We have to avoid using an address passed in via fuzz args,
        // cuz etching to `console.log` address will break this test.
        address deployer = _randomHashedAddress();

        // This is a minimal contract that uses the 'CREATE' opcode to deploy
        // the calldata and returns the addesss.
        vm.etch(deployer, hex"3d3d363d3d37363d34f09052602081f3");

        for (uint256 i; i != 3; ++i) {
            r = r >> 32;
            if (r & 31 == 0) {
                _testLifebuoyCreateDeployment(deployer, type(MockERC721).creationCode);
                continue;
            }
            r = r >> 8;
            if (r & 1 == 0) {
                bytes memory initcode = type(MockLifebuoyOwned).creationCode;
                initcode = abi.encodePacked(initcode, abi.encode(owner));
                _testLifebuoyCreateDeployment(deployer, initcode);
                continue;
            }
            _testLifebuoyCreateDeployment(deployer, type(MockLifebuoy).creationCode);
        }
    }

