            assertEq(expires, c.expires);
            assertEq(isActive, start <= targetTimestamp && targetTimestamp <= expires);
        }
        if (!_hasDuplicateKeys(a)) {
            for (uint256 i; i != a.length; ++i) {
                TimedRoleConfig memory c = a[i];
