        vm.prank(receiver, receiver);
        vm.expectRevert(abi.encodeWithSelector(Drop.DropClaimExceedLimit.selector, x, x + 5));
        openEdition.claim(receiver, 5, address(0), 0, alp, ""); // quantity limit already claimed
    }

